import { useState, useRef } from "react";

// ─── EMPLOYEES ────────────────────────────────────────────────────────────────
const INITIAL_EMPLOYEES = [
  { id: 0, name: "Conner",        role: "Manager",       avatar: "CO", lang: "en", workdays: "Mon–Sat", isManager: true },
  { id: 1, name: "Frank Solís",   role: "Driver",        avatar: "FS", lang: "en", workdays: "Mon–Fri" },
  { id: 2, name: "Max Applegate", role: "Driver",        avatar: "MA", lang: "en", workdays: "Mon–Fri" },
  { id: 3, name: "Chris Mullis",  role: "Driver",        avatar: "CM", lang: "en", workdays: "Mon–Fri" },
  { id: 4, name: "Nate",          role: "Driver/Helper", avatar: "NA", lang: "en", workdays: "Fri–Sat" },
  { id: 5, name: "Ricky Torres",  role: "Helper",        avatar: "RT", lang: "es", workdays: "Mon–Fri" },
  { id: 6, name: "Aariq Curtis",  role: "Helper",        avatar: "AC", lang: "en", workdays: "Mon–Fri" },
  { id: 7, name: "Alberto",       role: "Helper",        avatar: "AL", lang: "es", workdays: "Fri–Sat" },
];

const ESCALATION = {
  customer: ["Driver", "Conner (Manager)", "Scott / Brian / Cameron"],
  product:  ["Driver", "Conner (Manager)", "Vendor"],
};

const STATUS_COLORS = {
  "Scheduled":   { bg: "#1e293b", text: "#94a3b8", dot: "#64748b" },
  "In Transit":  { bg: "#0c2340", text: "#60a5fa", dot: "#3b82f6" },
  "Delivered":   { bg: "#052e16", text: "#4ade80", dot: "#22c55e" },
  "Rescheduled": { bg: "#1c1500", text: "#fbbf24", dot: "#f59e0b" },
  "Transfer":    { bg: "#1a0a2e", text: "#c084fc", dot: "#a855f7" },
  "Issue":       { bg: "#2d0a0a", text: "#f87171", dot: "#ef4444" },
};

const INITIAL_DELIVERIES = [
  { id: "D-001", customer: "Sarah Chen",      address: "142 Maple Ave",      phone: "555-0192", item: "King Pillow-Top",   window: "9AM–11AM",  assignedTo: 1, status: "In Transit",  notes: "",                      floor: "1", elevator: false, removalRequested: false, paymentStatus: "Paid", transferScheduled: false },
  { id: "D-002", customer: "Robert Okafor",   address: "78 Pine St, Apt 4B", phone: "555-0341", item: "Queen Memory Foam", window: "11AM–1PM",  assignedTo: 3, status: "Scheduled",  notes: "Large sectional in hall", floor: "3", elevator: false, removalRequested: true,  paymentStatus: "COD",  transferScheduled: false },
  { id: "D-003", customer: "Lisa Park",       address: "201 Birch Blvd",     phone: "555-0587", item: "Twin Firm + Frame", window: "1PM–3PM",   assignedTo: 1, status: "Scheduled",  notes: "",                      floor: "1", elevator: false, removalRequested: false, paymentStatus: "Paid", transferScheduled: false },
  { id: "D-004", customer: "James Whitfield", address: "55 Oak Court",       phone: "555-0764", item: "Cal King Luxury",   window: "2PM–4PM",   assignedTo: 2, status: "Delivered",  notes: "",                      floor: "2", elevator: true,  removalRequested: true,  paymentStatus: "Paid", transferScheduled: false },
  { id: "D-005", customer: "Nina Torres",     address: "390 Elm Drive",      phone: "555-0923", item: "Full Hybrid",       window: "3PM–5PM",   assignedTo: 2, status: "Scheduled",  notes: "",                      floor: "1", elevator: false, removalRequested: false, paymentStatus: "COD",  transferScheduled: true },
];

const TASK_TEMPLATES_EN = [
  "Load truck in designated sequence — heaviest items first, fragile bases last",
  "Verify all delivery addresses against manifest before departure",
  "Confirm mattress protector is included for each order",
  "Photograph items before loading and upon delivery",
  "Call customers 30 minutes before arrival",
  "Check hardware kit is complete for each bed frame",
  "Collect old mattress for disposal if removal requested",
  "Obtain digital signature from every customer",
  "Log delivery completion in the app immediately after drop-off",
  "Sweep and inspect truck bed at end of shift",
  "Restock packing blankets and straps at warehouse",
  "Report any vehicle issues before end of shift",
];

const TASK_TEMPLATES_ES = [
  "Cargar el camión en el orden correcto — los más pesados primero, las bases frágiles al final",
  "Verificar todas las direcciones de entrega con el manifiesto antes de salir",
  "Confirmar que el protector de colchón esté incluido en cada pedido",
  "Fotografiar los artículos antes de cargar y al momento de la entrega",
  "Llamar a los clientes 30 minutos antes de llegar",
  "Verificar que el kit de herraje esté completo para cada base de cama",
  "Recoger el colchón viejo si el cliente solicitó retiro",
  "Obtener firma digital de cada cliente",
  "Registrar la entrega en la aplicación inmediatamente después",
  "Limpiar e inspeccionar el camión al final del turno",
  "Reabastecer mantas y correas en el almacén",
  "Reportar cualquier problema del vehículo antes de terminar el turno",
];

const parseCSV = (text, currentEmployees) => {
  const lines = text.trim().split("\n");
  if (lines.length < 2) return [];
  const headers = lines[0].split(",").map(h => h.trim().toLowerCase().replace(/\s+/g, ""));
  return lines.slice(1).map((line, i) => {
    const vals = line.split(",").map(v => v.trim().replace(/^"|"$/g, ""));
    const row = {};
    headers.forEach((h, j) => row[h] = vals[j] || "");
    const empMatch = currentEmployees.find(e => e.name.toLowerCase().includes((row.assignedto || row.driver || "").toLowerCase()));
    return {
      id: `D-${String(i + 1).padStart(3, "0")}`,
      customer: row.customer || row.customername || `Customer ${i + 1}`,
      address: row.address || "",
      phone: row.phone || row.phonenumber || "",
      item: row.item || row.product || row.mattress || "",
      window: row.window || row.timewindow || row.time || "",
      assignedTo: empMatch ? empMatch.id : 1,
      status: row.status || "Scheduled",
      notes: row.notes || "",
      floor: row.floor || "1",
      elevator: (row.elevator || "").toLowerCase() === "yes",
      removalRequested: (row.removal || row.oldmattress || "").toLowerCase() === "yes",
      paymentStatus: row.payment || row.paymentstatus || "Paid",
      transferScheduled: (row.transfer || "").toLowerCase() === "yes",
    };
  });
};

// ─── ROLE OPTIONS ─────────────────────────────────────────────────────────────
const ROLES = ["Driver", "Helper", "Driver/Helper", "Coordinator", "Loader", "Manager", "Other"];
const WORKDAY_OPTIONS = ["Mon–Fri", "Mon–Sat", "Tue–Sat", "Wed–Sun", "Fri–Sat", "Sat–Sun", "Varies"];

export default function App() {
  const [tab, setTab] = useState("dashboard");
  const [employees, setEmployees] = useState(INITIAL_EMPLOYEES);
  const [deliveries, setDeliveries] = useState(INITIAL_DELIVERIES);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [tasks, setTasks] = useState({});
  const [generatingFor, setGeneratingFor] = useState(null);
  const [notes, setNotes] = useState({});
  const [noteInput, setNoteInput] = useState("");
  const [customerMsg, setCustomerMsg] = useState({});
  const [sendingMsg, setSendingMsg] = useState(null);
  const [msgSent, setMsgSent] = useState({});
  const [aiPrompt, setAiPrompt] = useState("");
  const [problems, setProblems] = useState([]);
  const [problemInput, setProblemInput] = useState({ empId: "", description: "", type: "customer" });
  const [schedules, setSchedules] = useState({});
  const [scheduleInput, setScheduleInput] = useState({});
  const [csvError, setCsvError] = useState("");
  const [newEmp, setNewEmp] = useState({ name: "", role: "Driver", lang: "en", workdays: "Mon–Fri" });
  const [addEmpError, setAddEmpError] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(null);
  const csvRef = useRef();
  const [todayDate] = useState(new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" }));

  const getEmployeeDeliveries = (empId) => deliveries.filter(d => d.assignedTo === empId);

  // ── Add / Remove Employees ──────────────────────────────────────────────────
  const addEmployee = () => {
    if (!newEmp.name.trim()) { setAddEmpError("Name is required."); return; }
    const initials = newEmp.name.trim().split(" ").map(w => w[0].toUpperCase()).join("").slice(0, 2);
    const nextId = Math.max(...employees.map(e => e.id)) + 1;
    setEmployees(prev => [...prev, {
      id: nextId, name: newEmp.name.trim(), role: newEmp.role,
      avatar: initials, lang: newEmp.lang, workdays: newEmp.workdays,
    }]);
    setNewEmp({ name: "", role: "Driver", lang: "en", workdays: "Mon–Fri" });
    setAddEmpError("");
  };

  const removeEmployee = (id) => {
    setEmployees(prev => prev.filter(e => e.id !== id));
    setConfirmDelete(null);
  };

  // ── AI Task Generation ──────────────────────────────────────────────────────
  const generateTasks = async (empId) => {
    setGeneratingFor(empId);
    const emp = employees.find(e => e.id === empId);
    const empDeliveries = getEmployeeDeliveries(empId);
    const isSpanish = emp.lang === "es";
    const langNote = isSpanish ? "IMPORTANT: Write ALL tasks in Spanish." : "";
    const prompt = `You are a mattress delivery operations manager at America's Mattress. Generate a detailed daily task list for ${emp.name}, a ${emp.role}.
Today they have ${empDeliveries.length} deliveries: ${empDeliveries.map(d =>
  `${d.customer} (${d.item}, ${d.window}${d.floor !== "1" ? `, floor ${d.floor}` : ""}${!d.elevator && d.floor !== "1" ? ", no elevator" : ""}${d.removalRequested ? ", old mattress removal" : ""}${d.transferScheduled ? ", transfer scheduled" : ""}${d.notes ? ", note: " + d.notes : ""})`
).join("; ")}.
${aiPrompt ? "Additional context: " + aiPrompt : ""}
${langNote}
Return ONLY a JSON array of task objects. Each: { "task": string, "duration": string, "priority": "high"|"medium"|"low", "category": ${isSpanish ? '"Preparación"|"Entrega"|"Admin"|"Fin de Turno"' : '"Prep"|"Delivery"|"Admin"|"End of Day"'} }.
Generate 8–12 tasks totaling 6–8 hours. Specific and practical. No markdown, no preamble — pure JSON only.`;
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model: "claude-sonnet-4-20250514", max_tokens: 1000, messages: [{ role: "user", content: prompt }] }),
      });
      const data = await res.json();
      const text = data.content.map(b => b.text || "").join("");
      setTasks(prev => ({ ...prev, [empId]: JSON.parse(text.replace(/```json|```/g, "").trim()) }));
    } catch {
      const tpl = isSpanish ? TASK_TEMPLATES_ES : TASK_TEMPLATES_EN;
      const cats = isSpanish ? ["Preparación", "Entrega", "Admin", "Fin de Turno"] : ["Prep", "Delivery", "Admin", "End of Day"];
      setTasks(prev => ({ ...prev, [empId]: [...tpl].sort(() => Math.random() - 0.5).slice(0, 9).map((t, i) => ({
        task: t, duration: ["45 min", "30 min", "1 hr", "20 min", "1.5 hr"][i % 5],
        priority: ["high", "medium", "low"][i % 3], category: cats[i % 4],
      })) }));
    }
    setGeneratingFor(null);
  };

  // ── SMS Generation ──────────────────────────────────────────────────────────
  const generateCustomerMsg = async (delivery) => {
    setSendingMsg(delivery.id);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model: "claude-sonnet-4-20250514", max_tokens: 200, messages: [{ role: "user", content: `Write a short friendly SMS under 160 chars for America's Mattress. Customer: ${delivery.customer}, Item: ${delivery.item}, Window: ${delivery.window}, Status: ${delivery.status}${delivery.notes ? ", Note: "+delivery.notes:""}. Return ONLY the SMS text.` }] }),
      });
      const data = await res.json();
      setCustomerMsg(prev => ({ ...prev, [delivery.id]: data.content.map(b => b.text || "").join("").trim() }));
    } catch {
      setCustomerMsg(prev => ({ ...prev, [delivery.id]: `Hi ${delivery.customer.split(" ")[0]}! Your ${delivery.item} is ${delivery.status.toLowerCase()} for ${delivery.window}. We'll call 30 min ahead! – America's Mattress` }));
    }
    setSendingMsg(null);
    setMsgSent(prev => ({ ...prev, [delivery.id]: true }));
    setTimeout(() => setMsgSent(prev => ({ ...prev, [delivery.id]: false })), 3000);
  };

  const updateStatus = (id, status) => setDeliveries(prev => prev.map(d => d.id === id ? { ...d, status } : d));

  const addNote = (empId) => {
    if (!noteInput.trim()) return;
    const ts = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    setNotes(prev => ({ ...prev, [empId]: [...(prev[empId] || []), { text: noteInput.trim(), time: ts, id: Date.now() }] }));
    setNoteInput("");
  };

  const logProblem = () => {
    if (!problemInput.description.trim() || !problemInput.empId) return;
    const emp = employees.find(e => e.id === Number(problemInput.empId));
    setProblems(prev => [...prev, {
      id: Date.now(), empName: emp?.name, description: problemInput.description,
      type: problemInput.type, escalationStep: 0,
      time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }), resolved: false,
    }]);
    setProblemInput({ empId: "", description: "", type: "customer" });
  };

  const escalateProblem = (id) => {
    setProblems(prev => prev.map(p => {
      if (p.id !== id) return p;
      const chain = ESCALATION[p.type];
      const next = Math.min(p.escalationStep + 1, chain.length - 1);
      return { ...p, escalationStep: next, resolved: next === chain.length - 1 };
    }));
  };

  const handleCSV = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const parsed = parseCSV(ev.target.result, employees);
        if (!parsed.length) { setCsvError("No data found. Check CSV format."); return; }
        setDeliveries(parsed);
        setCsvError("");
      } catch { setCsvError("Failed to parse CSV. Check format and try again."); }
    };
    reader.readAsText(file);
  };

  const saveSchedule = (empId) => {
    if (!scheduleInput[empId]?.trim()) return;
    setSchedules(prev => ({ ...prev, [empId]: scheduleInput[empId].trim() }));
    setScheduleInput(prev => ({ ...prev, [empId]: "" }));
  };

  const stats = {
    total: deliveries.length,
    delivered: deliveries.filter(d => d.status === "Delivered").length,
    inTransit: deliveries.filter(d => d.status === "In Transit").length,
    scheduled: deliveries.filter(d => d.status === "Scheduled").length,
    issues: deliveries.filter(d => d.status === "Issue" || d.status === "Rescheduled").length,
  };

  const S = {
    card: { background: "#0f1923", border: "1px solid #1e2d3d", borderRadius: 12 },
    label: { fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", color: "#475569", textTransform: "uppercase", marginBottom: 10 },
    input: { background: "#0a1628", border: "1px solid #1e2d3d", borderRadius: 8, padding: "9px 13px", fontSize: 13, color: "#e2e8f0", width: "100%" },
    select: { background: "#0a1628", border: "1px solid #1e2d3d", borderRadius: 8, padding: "9px 12px", fontSize: 13, color: "#e2e8f0", width: "100%" },
  };

  const avatarBg = (emp) => emp.isManager
    ? "linear-gradient(135deg,#7c3aed,#4f46e5)"
    : emp.lang === "es"
    ? "linear-gradient(135deg,#059669,#047857)"
    : "linear-gradient(135deg,#1d4ed8,#0ea5e9)";

  return (
    <div style={{ fontFamily: "'DM Sans','Segoe UI',sans-serif", background: "#080d14", minHeight: "100vh", color: "#e2e8f0" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&family=DM+Mono:wght@400;500&display=swap');
        *{box-sizing:border-box;margin:0;padding:0}
        ::-webkit-scrollbar{width:4px}::-webkit-scrollbar-track{background:#0f1923}::-webkit-scrollbar-thumb{background:#334155;border-radius:2px}
        .btn{border:none;cursor:pointer;font-family:inherit;border-radius:8px;font-weight:500;transition:all .15s}
        .btn:hover{opacity:.85;transform:translateY(-1px)}.btn:active{transform:translateY(0)}
        .btn:disabled{opacity:.4;cursor:not-allowed;transform:none}
        .badge{display:inline-flex;align-items:center;gap:5px;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:600;letter-spacing:.04em}
        .card-hover:hover{border-color:#334155!important;background:#131f2e!important}
        .pulse{animation:pulse 2s infinite}
        @keyframes pulse{0%,100%{opacity:1}50%{opacity:.5}}
        .fade-in{animation:fadeIn .3s ease}
        @keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
        input,textarea,select{font-family:inherit;color:#e2e8f0}
        .tab-btn{background:none;border:none;cursor:pointer;font-family:inherit;transition:all .2s}
      `}</style>

      {/* HEADER */}
      <div style={{ background: "#0a1628", borderBottom: "1px solid #1e2d3d" }}>
        <div style={{ maxWidth: 1160, margin: "0 auto", padding: "0 24px", display: "flex", alignItems: "center", justifyContent: "space-between", height: 64 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ width: 38, height: 38, background: "linear-gradient(135deg,#2563eb,#1d4ed8)", borderRadius: 10, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20 }}>🛏</div>
            <div>
              <div style={{ fontWeight: 800, fontSize: 15, letterSpacing: "-.02em", color: "#f1f5f9" }}>America's Mattress</div>
              <div style={{ fontSize: 11, color: "#475569", fontFamily: "'DM Mono',monospace" }}>Operations Hub · {employees.length} team members</div>
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ fontSize: 12, color: "#475569" }}>{todayDate}</div>
            <div style={{ width: 36, height: 36, borderRadius: "50%", background: "linear-gradient(135deg,#7c3aed,#4f46e5)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 800, color: "#fff" }}>CO</div>
            <label style={{ background: "#1e2d3d", color: "#94a3b8", padding: "7px 14px", borderRadius: 8, fontSize: 12, cursor: "pointer", fontWeight: 500 }}>
              📂 Import CSV
              <input ref={csvRef} type="file" accept=".csv" onChange={handleCSV} style={{ display: "none" }} />
            </label>
          </div>
        </div>
        {csvError && <div style={{ background: "#2d0a0a", color: "#f87171", padding: "8px 24px", fontSize: 12 }}>⚠️ {csvError}</div>}
      </div>

      {/* NAV */}
      <div style={{ background: "#0a1628", borderBottom: "1px solid #1e2d3d" }}>
        <div style={{ maxWidth: 1160, margin: "0 auto", padding: "0 24px", display: "flex", gap: 2, overflowX: "auto" }}>
          {[
            { key: "dashboard",  label: "Dashboard",    icon: "⬛" },
            { key: "tasks",      label: "Daily Tasks",  icon: "✅" },
            { key: "schedules",  label: "Schedules",    icon: "📅" },
            { key: "deliveries", label: "Deliveries",   icon: "🚛" },
            { key: "problems",   label: "Problems",     icon: "⚠️" },
            { key: "comms",      label: "Customer SMS", icon: "💬" },
            { key: "team",       label: "Team",         icon: "👥" },
          ].map(t => (
            <button key={t.key} className="tab-btn" onClick={() => setTab(t.key)}
              style={{ padding: "14px 14px", fontSize: 13, fontWeight: 500, whiteSpace: "nowrap",
                color: tab === t.key ? "#60a5fa" : "#64748b",
                borderBottom: tab === t.key ? "2px solid #3b82f6" : "2px solid transparent" }}>
              {t.icon} {t.label}
              {t.key === "problems" && problems.filter(p => !p.resolved).length > 0 &&
                <span style={{ marginLeft: 5, background: "#ef4444", color: "#fff", borderRadius: 10, padding: "1px 6px", fontSize: 10 }}>
                  {problems.filter(p => !p.resolved).length}
                </span>}
            </button>
          ))}
        </div>
      </div>

      <div style={{ maxWidth: 1160, margin: "0 auto", padding: "24px" }}>

        {/* ══ DASHBOARD ══ */}
        {tab === "dashboard" && (
          <div className="fade-in">
            <div style={{ display: "grid", gridTemplateColumns: "repeat(5,1fr)", gap: 14, marginBottom: 28 }}>
              {[
                { label: "Total",      val: stats.total,     color: "#3b82f6", icon: "📦" },
                { label: "Scheduled",  val: stats.scheduled, color: "#64748b", icon: "🕐" },
                { label: "In Transit", val: stats.inTransit, color: "#3b82f6", icon: "🚛" },
                { label: "Delivered",  val: stats.delivered, color: "#22c55e", icon: "✅" },
                { label: "Issues",     val: stats.issues,    color: "#ef4444", icon: "⚠️" },
              ].map(s => (
                <div key={s.label} style={{ ...S.card, padding: "18px 20px" }}>
                  <div style={{ fontSize: 22, marginBottom: 6 }}>{s.icon}</div>
                  <div style={{ fontSize: 30, fontWeight: 700, color: s.color, fontFamily: "'DM Mono',monospace", lineHeight: 1 }}>{s.val}</div>
                  <div style={{ fontSize: 11, color: "#475569", marginTop: 5, fontWeight: 500 }}>{s.label}</div>
                </div>
              ))}
            </div>

            <div style={S.label}>Team Overview</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12, marginBottom: 28 }}>
              {employees.map(emp => {
                const eds = getEmployeeDeliveries(emp.id);
                const done = eds.filter(d => d.status === "Delivered").length;
                const pct = eds.length ? Math.round((done / eds.length) * 100) : 0;
                return (
                  <div key={emp.id} style={{ ...S.card, padding: "16px 18px", cursor: "pointer", transition: "all .2s" }} className="card-hover"
                    onClick={() => { setTab("tasks"); setSelectedEmployee(emp.id); }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
                      <div style={{ width: 36, height: 36, borderRadius: "50%", background: avatarBg(emp), display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, color: "#fff", flexShrink: 0 }}>{emp.avatar}</div>
                      <div>
                        <div style={{ fontWeight: 600, fontSize: 13, color: "#f1f5f9" }}>{emp.name}{emp.isManager ? " 👑" : ""}{emp.lang === "es" ? " 🇲🇽" : ""}</div>
                        <div style={{ fontSize: 10, color: "#475569" }}>{emp.role}</div>
                      </div>
                    </div>
                    <div style={{ height: 3, background: "#1e2d3d", borderRadius: 2, overflow: "hidden", marginBottom: 6 }}>
                      <div style={{ height: "100%", width: `${pct}%`, background: "linear-gradient(90deg,#2563eb,#22c55e)", borderRadius: 2, transition: "width .6s" }} />
                    </div>
                    <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10, color: "#475569" }}>
                      <span>{done}/{eds.length} deliveries</span>
                      <span style={{ color: pct === 100 ? "#22c55e" : "#60a5fa", fontWeight: 600 }}>{pct}%</span>
                    </div>
                  </div>
                );
              })}
            </div>

            <div style={S.label}>Today's Schedule</div>
            <div style={{ ...S.card, overflow: "hidden" }}>
              {deliveries.map((d, i) => {
                const emp = employees.find(e => e.id === d.assignedTo);
                const sc = STATUS_COLORS[d.status] || STATUS_COLORS["Scheduled"];
                return (
                  <div key={d.id} style={{ display: "flex", alignItems: "center", padding: "13px 20px", borderBottom: i < deliveries.length - 1 ? "1px solid #131f2e" : "none", gap: 14, flexWrap: "wrap" }}>
                    <span style={{ fontFamily: "'DM Mono',monospace", fontSize: 10, color: "#475569", width: 48 }}>{d.id}</span>
                    <div style={{ flex: 1, minWidth: 140 }}>
                      <div style={{ fontWeight: 600, fontSize: 13, color: "#e2e8f0" }}>{d.customer}</div>
                      <div style={{ fontSize: 11, color: "#475569" }}>{d.item}</div>
                    </div>
                    <div style={{ fontSize: 11, color: "#64748b", width: 80 }}>{d.window}</div>
                    <div style={{ fontSize: 11, color: "#64748b", width: 100 }}>{emp?.name}</div>
                    <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
                      {d.removalRequested && <span style={{ fontSize: 10, background: "#1c1500", color: "#f59e0b", borderRadius: 4, padding: "2px 6px" }}>♻️ Removal</span>}
                      {d.transferScheduled && <span style={{ fontSize: 10, background: "#1a0a2e", color: "#c084fc", borderRadius: 4, padding: "2px 6px" }}>🔄 Transfer</span>}
                      {d.floor !== "1" && <span style={{ fontSize: 10, background: "#0a1628", color: "#60a5fa", borderRadius: 4, padding: "2px 6px" }}>{d.elevator ? "🛗" : "🪜"} Fl {d.floor}</span>}
                    </div>
                    <span className="badge" style={{ background: sc.bg, color: sc.text }}>
                      <span style={{ width: 6, height: 6, borderRadius: "50%", background: sc.dot, ...(d.status === "In Transit" ? { animation: "pulse 2s infinite" } : {}) }} />
                      {d.status}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ══ DAILY TASKS ══ */}
        {tab === "tasks" && (
          <div className="fade-in">
            <div style={{ display: "flex", gap: 12, marginBottom: 20, flexWrap: "wrap", alignItems: "center" }}>
              <input value={aiPrompt} onChange={e => setAiPrompt(e.target.value)}
                placeholder="Add context for AI (e.g. 'short-staffed today, focus on afternoon route')..."
                style={{ flex: 1, minWidth: 200, ...S.input }} />
              <button className="btn" onClick={() => employees.filter(e => !e.isManager).forEach(e => generateTasks(e.id))}
                style={{ background: "linear-gradient(135deg,#2563eb,#1d4ed8)", color: "#fff", padding: "10px 20px", fontSize: 13 }}>
                ⚡ Generate All
              </button>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "220px 1fr", gap: 20 }}>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {employees.map(emp => (
                  <button key={emp.id} className="btn card-hover" onClick={() => setSelectedEmployee(emp.id)}
                    style={{ ...S.card, padding: "11px 14px", textAlign: "left", display: "flex", alignItems: "center", gap: 10,
                      borderColor: selectedEmployee === emp.id ? "#3b82f6" : "#1e2d3d",
                      background: selectedEmployee === emp.id ? "#0c1f38" : "#0f1923" }}>
                    <div style={{ width: 32, height: 32, borderRadius: "50%", background: avatarBg(emp), display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, color: "#fff", flexShrink: 0 }}>{emp.avatar}</div>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 600, fontSize: 12, color: "#f1f5f9" }}>{emp.name}{emp.isManager ? " 👑" : ""}{emp.lang === "es" ? " 🇲🇽" : ""}</div>
                      <div style={{ fontSize: 10, color: "#475569" }}>{emp.role} · {emp.workdays}</div>
                    </div>
                    {tasks[emp.id] && <span style={{ width: 7, height: 7, borderRadius: "50%", background: "#22c55e", flexShrink: 0 }} />}
                  </button>
                ))}
              </div>
              <div>
                {!selectedEmployee ? (
                  <div style={{ ...S.card, padding: 48, textAlign: "center", color: "#475569" }}>
                    <div style={{ fontSize: 36, marginBottom: 10 }}>👈</div>
                    <div>Select an employee to view or generate their task list</div>
                  </div>
                ) : (() => {
                  const emp = employees.find(e => e.id === selectedEmployee);
                  if (!emp) return null;
                  const empTasks = tasks[selectedEmployee];
                  const empNotes = notes[selectedEmployee] || [];
                  const cats = empTasks ? [...new Set(empTasks.map(t => t.category))] : [];
                  return (
                    <div>
                      <div style={{ ...S.card, padding: "18px 22px", marginBottom: 14, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <div>
                          <div style={{ fontWeight: 700, fontSize: 17, color: "#f1f5f9" }}>{emp.name}'s {emp.lang === "es" ? "Turno de Hoy" : "Day"}{emp.isManager ? " 👑" : ""}</div>
                          <div style={{ fontSize: 12, color: "#475569", marginTop: 2 }}>{emp.role} · {getEmployeeDeliveries(emp.id).length} deliveries assigned</div>
                        </div>
                        <button className="btn" onClick={() => generateTasks(selectedEmployee)} disabled={generatingFor === selectedEmployee}
                          style={{ background: generatingFor === selectedEmployee ? "#1e2d3d" : "linear-gradient(135deg,#2563eb,#1d4ed8)", color: generatingFor === selectedEmployee ? "#475569" : "#fff", padding: "9px 18px", fontSize: 13 }}>
                          {generatingFor === selectedEmployee ? "⏳ Generando..." : `⚡ ${emp.lang === "es" ? "Generar Tareas" : "Generate Tasks"}`}
                        </button>
                      </div>
                      {empTasks && (
                        <div style={{ ...S.card, marginBottom: 14 }}>
                          {cats.map(cat => (
                            <div key={cat}>
                              <div style={{ padding: "9px 20px", background: "#0a1628", fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", color: "#475569", textTransform: "uppercase", borderBottom: "1px solid #131f2e" }}>{cat}</div>
                              {empTasks.filter(t => t.category === cat).map((task, i) => (
                                <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 12, padding: "13px 20px", borderBottom: "1px solid #0f1923" }}>
                                  <div style={{ width: 7, height: 7, borderRadius: "50%", background: task.priority === "high" ? "#ef4444" : task.priority === "medium" ? "#f59e0b" : "#475569", marginTop: 6, flexShrink: 0 }} />
                                  <div style={{ flex: 1 }}>
                                    <div style={{ fontSize: 13, color: "#e2e8f0", fontWeight: 500 }}>{task.task}</div>
                                    <div style={{ fontSize: 11, color: "#475569", marginTop: 2 }}>Est. {task.duration}</div>
                                  </div>
                                  <span style={{ fontSize: 10, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: task.priority === "high" ? "#ef4444" : task.priority === "medium" ? "#f59e0b" : "#475569" }}>{task.priority}</span>
                                </div>
                              ))}
                            </div>
                          ))}
                        </div>
                      )}
                      <div style={{ ...S.card, padding: "18px 22px" }}>
                        <div style={{ fontWeight: 600, fontSize: 13, color: "#f1f5f9", marginBottom: 12 }}>💬 {emp.lang === "es" ? "Notas del Gerente" : "Manager Notes"}</div>
                        {empNotes.map(n => (
                          <div key={n.id} style={{ background: "#0a1628", borderRadius: 7, padding: "9px 13px", marginBottom: 7, display: "flex", justifyContent: "space-between" }}>
                            <span style={{ fontSize: 13, color: "#cbd5e1" }}>{n.text}</span>
                            <span style={{ fontSize: 10, color: "#475569", marginLeft: 12, flexShrink: 0 }}>{n.time}</span>
                          </div>
                        ))}
                        <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                          <input value={noteInput} onChange={e => setNoteInput(e.target.value)}
                            onKeyDown={e => e.key === "Enter" && addNote(selectedEmployee)}
                            placeholder={emp.lang === "es" ? "Añadir nota para este empleado..." : "Add a note for this employee..."}
                            style={{ flex: 1, ...S.input }} />
                          <button className="btn" onClick={() => addNote(selectedEmployee)} style={{ background: "#1e2d3d", color: "#94a3b8", padding: "9px 16px", fontSize: 13 }}>Add</button>
                        </div>
                      </div>
                    </div>
                  );
                })()}
              </div>
            </div>
          </div>
        )}

        {/* ══ SCHEDULES ══ */}
        {tab === "schedules" && (
          <div className="fade-in">
            <div style={S.label}>Employee Weekly Schedules</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 14 }}>
              {employees.map(emp => {
                const sched = schedules[emp.id];
                const isEs = emp.lang === "es";
                return (
                  <div key={emp.id} style={{ ...S.card, padding: "18px 22px" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
                      <div style={{ width: 36, height: 36, borderRadius: "50%", background: avatarBg(emp), display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, color: "#fff" }}>{emp.avatar}</div>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 14, color: "#f1f5f9" }}>{emp.name}{emp.isManager ? " 👑" : ""}{isEs ? " 🇲🇽" : ""}</div>
                        <div style={{ fontSize: 11, color: "#475569" }}>{emp.role} · Default: {emp.workdays}</div>
                      </div>
                    </div>
                    {sched ? (
                      <div style={{ background: "#0a1628", borderRadius: 8, padding: "12px 14px", marginBottom: 10 }}>
                        <div style={{ fontSize: 10, fontWeight: 700, color: "#475569", letterSpacing: ".08em", textTransform: "uppercase", marginBottom: 6 }}>{isEs ? "Horario Actual" : "Current Schedule"}</div>
                        <div style={{ fontSize: 13, color: "#e2e8f0", whiteSpace: "pre-wrap", lineHeight: 1.7 }}>{sched}</div>
                      </div>
                    ) : (
                      <div style={{ fontSize: 12, color: "#334155", fontStyle: "italic", marginBottom: 10 }}>{isEs ? "No hay horario cargado." : "No schedule uploaded yet."}</div>
                    )}
                    <textarea value={scheduleInput[emp.id] || ""}
                      onChange={e => setScheduleInput(prev => ({ ...prev, [emp.id]: e.target.value }))}
                      placeholder={isEs ? "Pegar o escribir el horario de la semana..." : "Paste or type this week's schedule..."}
                      rows={3} style={{ ...S.input, resize: "vertical", marginBottom: 8 }} />
                    <button className="btn" onClick={() => saveSchedule(emp.id)}
                      style={{ background: "linear-gradient(135deg,#2563eb,#1d4ed8)", color: "#fff", padding: "8px 16px", fontSize: 12 }}>
                      {isEs ? "💾 Guardar Horario" : "💾 Save Schedule"}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ══ DELIVERIES ══ */}
        {tab === "deliveries" && (
          <div className="fade-in">
            <div style={{ display: "flex", gap: 10, marginBottom: 20, flexWrap: "wrap" }}>
              {Object.entries(STATUS_COLORS).map(([s, c]) => (
                <span key={s} className="badge" style={{ background: c.bg, color: c.text, padding: "5px 12px" }}>
                  <span style={{ width: 6, height: 6, borderRadius: "50%", background: c.dot }} />
                  {s} — {deliveries.filter(d => d.status === s).length}
                </span>
              ))}
              <label style={{ background: "#1e2d3d", color: "#94a3b8", padding: "5px 14px", borderRadius: 20, fontSize: 11, cursor: "pointer", display: "flex", alignItems: "center", gap: 5, fontWeight: 600 }}>
                📂 Import CSV <input type="file" accept=".csv" onChange={handleCSV} style={{ display: "none" }} />
              </label>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {deliveries.map(d => {
                const emp = employees.find(e => e.id === d.assignedTo);
                const sc = STATUS_COLORS[d.status] || STATUS_COLORS["Scheduled"];
                return (
                  <div key={d.id} style={{ ...S.card, padding: "18px 22px" }}>
                    <div style={{ display: "flex", gap: 20, flexWrap: "wrap" }}>
                      <div style={{ flex: 1, minWidth: 180 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 5 }}>
                          <span style={{ fontFamily: "'DM Mono',monospace", fontSize: 10, color: "#475569" }}>{d.id}</span>
                          <span className="badge" style={{ background: sc.bg, color: sc.text }}>
                            <span style={{ width: 5, height: 5, borderRadius: "50%", background: sc.dot, ...(d.status === "In Transit" ? { animation: "pulse 2s infinite" } : {}) }} />
                            {d.status}
                          </span>
                        </div>
                        <div style={{ fontWeight: 700, fontSize: 15, color: "#f1f5f9" }}>{d.customer}</div>
                        <div style={{ fontSize: 12, color: "#64748b", marginTop: 2 }}>{d.address}</div>
                        <div style={{ fontSize: 12, color: "#64748b" }}>{d.phone}</div>
                        <div style={{ display: "flex", gap: 6, marginTop: 8, flexWrap: "wrap" }}>
                          <span style={{ fontSize: 10, background: d.paymentStatus === "COD" ? "#1c1500" : "#052e16", color: d.paymentStatus === "COD" ? "#fbbf24" : "#4ade80", borderRadius: 4, padding: "2px 7px", fontWeight: 600 }}>{d.paymentStatus}</span>
                          {d.removalRequested && <span style={{ fontSize: 10, background: "#1c1500", color: "#f59e0b", borderRadius: 4, padding: "2px 7px" }}>♻️ Old Removal</span>}
                          {d.transferScheduled && <span style={{ fontSize: 10, background: "#1a0a2e", color: "#c084fc", borderRadius: 4, padding: "2px 7px" }}>🔄 Transfer</span>}
                          {d.floor !== "1" && <span style={{ fontSize: 10, background: "#0a1628", color: "#60a5fa", borderRadius: 4, padding: "2px 7px" }}>{d.elevator ? "🛗 Elevator" : `🪜 Floor ${d.floor}, No Elevator`}</span>}
                        </div>
                      </div>
                      <div style={{ minWidth: 140 }}>
                        <div style={{ fontSize: 10, color: "#475569", marginBottom: 3, textTransform: "uppercase", letterSpacing: ".06em" }}>Item</div>
                        <div style={{ fontWeight: 600, color: "#e2e8f0", fontSize: 13 }}>{d.item}</div>
                        <div style={{ fontSize: 10, color: "#475569", marginTop: 10, marginBottom: 3, textTransform: "uppercase", letterSpacing: ".06em" }}>Window</div>
                        <div style={{ fontWeight: 500, color: "#60a5fa", fontSize: 13 }}>{d.window}</div>
                        <div style={{ fontSize: 10, color: "#475569", marginTop: 10, marginBottom: 3, textTransform: "uppercase", letterSpacing: ".06em" }}>Driver</div>
                        <div style={{ fontWeight: 600, color: "#e2e8f0", fontSize: 13 }}>{emp?.name}</div>
                        {d.notes && <div style={{ fontSize: 10, color: "#f59e0b", marginTop: 8, background: "#1c1500", borderRadius: 5, padding: "3px 7px" }}>⚠️ {d.notes}</div>}
                      </div>
                      <div style={{ display: "flex", flexDirection: "column", gap: 6, minWidth: 130 }}>
                        <div style={{ fontSize: 10, color: "#475569", textTransform: "uppercase", letterSpacing: ".06em", marginBottom: 2 }}>Update Status</div>
                        {Object.keys(STATUS_COLORS).map(s => (
                          <button key={s} className="btn" onClick={() => updateStatus(d.id, s)}
                            style={{ background: d.status === s ? STATUS_COLORS[s].bg : "#0a1628", color: d.status === s ? STATUS_COLORS[s].text : "#475569", border: `1px solid ${d.status === s ? STATUS_COLORS[s].dot : "#1e2d3d"}`, padding: "5px 10px", fontSize: 11, textAlign: "left" }}>
                            {s}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ══ PROBLEMS ══ */}
        {tab === "problems" && (
          <div className="fade-in">
            <div style={{ ...S.card, padding: "20px 24px", marginBottom: 20 }}>
              <div style={{ fontWeight: 700, fontSize: 15, color: "#f1f5f9", marginBottom: 16 }}>⚠️ Log a Daily Problem</div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 }}>
                <div>
                  <div style={{ fontSize: 11, color: "#475569", marginBottom: 5 }}>Employee</div>
                  <select value={problemInput.empId} onChange={e => setProblemInput(p => ({ ...p, empId: e.target.value }))} style={S.select}>
                    <option value="">Select employee...</option>
                    {employees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
                  </select>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: "#475569", marginBottom: 5 }}>Problem Type</div>
                  <select value={problemInput.type} onChange={e => setProblemInput(p => ({ ...p, type: e.target.value }))} style={S.select}>
                    <option value="customer">Customer Issue</option>
                    <option value="product">Product / Vendor Issue</option>
                  </select>
                </div>
              </div>
              <div style={{ marginBottom: 12 }}>
                <div style={{ fontSize: 11, color: "#475569", marginBottom: 5 }}>Description</div>
                <textarea value={problemInput.description} onChange={e => setProblemInput(p => ({ ...p, description: e.target.value }))}
                  placeholder="Describe the problem in detail..." rows={3} style={{ ...S.input, resize: "vertical" }} />
              </div>
              <button className="btn" onClick={logProblem}
                style={{ background: "linear-gradient(135deg,#dc2626,#b91c1c)", color: "#fff", padding: "9px 20px", fontSize: 13 }}>
                ⚠️ Log Problem
              </button>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 20 }}>
              {Object.entries(ESCALATION).map(([type, chain]) => (
                <div key={type} style={{ ...S.card, padding: "16px 20px" }}>
                  <div style={{ fontWeight: 600, fontSize: 13, color: "#f1f5f9", marginBottom: 12 }}>
                    {type === "customer" ? "👤 Customer Issue Chain" : "📦 Product / Vendor Chain"}
                  </div>
                  {chain.map((step, i) => (
                    <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: i < chain.length - 1 ? 8 : 0 }}>
                      <div style={{ width: 24, height: 24, borderRadius: "50%", background: i === 0 ? "#1e2d3d" : i === 1 ? "#2d1a5e" : "#052e16", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, color: i === 0 ? "#94a3b8" : i === 1 ? "#a78bfa" : "#4ade80", flexShrink: 0 }}>{i + 1}</div>
                      <div style={{ fontSize: 13, color: i === 1 ? "#a78bfa" : "#e2e8f0", fontWeight: i === 1 ? 600 : 400 }}>{step}</div>
                      {i < chain.length - 1 && <div style={{ marginLeft: "auto", color: "#475569", fontSize: 12 }}>→</div>}
                    </div>
                  ))}
                </div>
              ))}
            </div>
            {problems.length === 0 ? (
              <div style={{ ...S.card, padding: 40, textAlign: "center", color: "#475569" }}>
                <div style={{ fontSize: 32, marginBottom: 8 }}>✅</div>
                <div>No problems logged today.</div>
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                {problems.map(p => {
                  const chain = ESCALATION[p.type];
                  const nextLevel = chain[p.escalationStep + 1];
                  return (
                    <div key={p.id} style={{ ...S.card, padding: "18px 22px", borderColor: p.resolved ? "#1e3a20" : "#3d1515" }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10, flexWrap: "wrap", gap: 10 }}>
                        <div>
                          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                            <span style={{ fontWeight: 700, fontSize: 14, color: "#f1f5f9" }}>{p.empName}</span>
                            <span className="badge" style={{ background: p.type === "customer" ? "#0c2340" : "#1a0a2e", color: p.type === "customer" ? "#60a5fa" : "#c084fc" }}>
                              {p.type === "customer" ? "👤 Customer" : "📦 Product"}
                            </span>
                            {p.resolved && <span className="badge" style={{ background: "#052e16", color: "#4ade80" }}>✅ Resolved</span>}
                          </div>
                          <div style={{ fontSize: 13, color: "#cbd5e1" }}>{p.description}</div>
                          <div style={{ fontSize: 10, color: "#475569", marginTop: 4 }}>Logged at {p.time}</div>
                        </div>
                        {!p.resolved && nextLevel && (
                          <button className="btn" onClick={() => escalateProblem(p.id)}
                            style={{ background: "linear-gradient(135deg,#d97706,#b45309)", color: "#fff", padding: "8px 16px", fontSize: 12 }}>
                            ↑ Escalate to {nextLevel}
                          </button>
                        )}
                      </div>
                      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                        {chain.map((step, i) => (
                          <div key={i} style={{ display: "flex", alignItems: "center", gap: 5, background: i <= p.escalationStep ? (i === p.escalationStep ? "#0c2340" : "#052e16") : "#0a1628", borderRadius: 6, padding: "5px 10px", border: `1px solid ${i === p.escalationStep ? "#3b82f6" : "#1e2d3d"}` }}>
                            <span style={{ width: 6, height: 6, borderRadius: "50%", background: i < p.escalationStep ? "#22c55e" : i === p.escalationStep ? "#3b82f6" : "#334155" }} />
                            <span style={{ fontSize: 11, color: i <= p.escalationStep ? "#e2e8f0" : "#475569" }}>{step}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ══ CUSTOMER SMS ══ */}
        {tab === "comms" && (
          <div className="fade-in">
            <div style={{ marginBottom: 14, fontSize: 13, color: "#475569" }}>AI-written SMS notifications personalized to each customer's delivery status.</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {deliveries.map(d => {
                const sc = STATUS_COLORS[d.status] || STATUS_COLORS["Scheduled"];
                const msg = customerMsg[d.id];
                const sent = msgSent[d.id];
                const loading = sendingMsg === d.id;
                return (
                  <div key={d.id} style={{ ...S.card, padding: "18px 22px" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12, flexWrap: "wrap", gap: 10 }}>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 14, color: "#f1f5f9" }}>{d.customer}</div>
                        <div style={{ fontSize: 11, color: "#64748b" }}>{d.phone} · {d.item} · {d.window}</div>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <span className="badge" style={{ background: sc.bg, color: sc.text }}>
                          <span style={{ width: 5, height: 5, borderRadius: "50%", background: sc.dot }} />{d.status}
                        </span>
                        <button className="btn" onClick={() => generateCustomerMsg(d)} disabled={loading}
                          style={{ background: loading ? "#1e2d3d" : "linear-gradient(135deg,#2563eb,#1d4ed8)", color: loading ? "#475569" : "#fff", padding: "7px 14px", fontSize: 12 }}>
                          {loading ? "⏳ Writing..." : "✨ Generate SMS"}
                        </button>
                      </div>
                    </div>
                    {msg ? (
                      <div style={{ background: "#0a1628", borderRadius: 9, padding: "13px 16px", display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
                        <div>
                          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: ".08em", color: "#475569", textTransform: "uppercase", marginBottom: 5 }}>Message Preview</div>
                          <div style={{ fontSize: 13, color: "#e2e8f0", lineHeight: 1.6 }}>{msg}</div>
                          <div style={{ fontSize: 10, color: msg.length > 150 ? "#f59e0b" : "#475569", marginTop: 5 }}>{msg.length}/160 chars</div>
                        </div>
                        <button className="btn" onClick={() => setMsgSent(p => ({ ...p, [d.id]: true }))}
                          style={{ background: sent ? "#052e16" : "#1e2d3d", color: sent ? "#4ade80" : "#94a3b8", padding: "7px 14px", fontSize: 12, flexShrink: 0 }}>
                          {sent ? "✓ Sent" : "📤 Send"}
                        </button>
                      </div>
                    ) : (
                      <div style={{ background: "#0a1628", borderRadius: 9, padding: "12px 16px", fontSize: 12, color: "#334155", fontStyle: "italic" }}>
                        Click "Generate SMS" to create a personalized message.
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ══ TEAM MANAGEMENT ══ */}
        {tab === "team" && (
          <div className="fade-in">
            {/* Add New Employee */}
            <div style={{ ...S.card, padding: "22px 26px", marginBottom: 24, borderColor: "#1e3a5f" }}>
              <div style={{ fontWeight: 700, fontSize: 15, color: "#f1f5f9", marginBottom: 18 }}>➕ Add New Employee</div>
              <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr", gap: 12, marginBottom: 14 }}>
                <div>
                  <div style={{ fontSize: 11, color: "#475569", marginBottom: 5 }}>Full Name *</div>
                  <input value={newEmp.name} onChange={e => setNewEmp(p => ({ ...p, name: e.target.value }))}
                    onKeyDown={e => e.key === "Enter" && addEmployee()}
                    placeholder="e.g. Maria Lopez"
                    style={S.input} />
                </div>
                <div>
                  <div style={{ fontSize: 11, color: "#475569", marginBottom: 5 }}>Role</div>
                  <select value={newEmp.role} onChange={e => setNewEmp(p => ({ ...p, role: e.target.value }))} style={S.select}>
                    {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: "#475569", marginBottom: 5 }}>Workdays</div>
                  <select value={newEmp.workdays} onChange={e => setNewEmp(p => ({ ...p, workdays: e.target.value }))} style={S.select}>
                    {WORKDAY_OPTIONS.map(w => <option key={w} value={w}>{w}</option>)}
                  </select>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: "#475569", marginBottom: 5 }}>Language</div>
                  <select value={newEmp.lang} onChange={e => setNewEmp(p => ({ ...p, lang: e.target.value }))} style={S.select}>
                    <option value="en">English 🇺🇸</option>
                    <option value="es">Spanish 🇲🇽</option>
                  </select>
                </div>
              </div>
              {addEmpError && <div style={{ fontSize: 12, color: "#f87171", marginBottom: 10 }}>⚠️ {addEmpError}</div>}
              <button className="btn" onClick={addEmployee}
                style={{ background: "linear-gradient(135deg,#059669,#047857)", color: "#fff", padding: "10px 22px", fontSize: 13 }}>
                ➕ Add to Team
              </button>
            </div>

            {/* Current Team */}
            <div style={S.label}>Current Team — {employees.length} members</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12 }}>
              {employees.map(emp => (
                <div key={emp.id} style={{ ...S.card, padding: "18px 22px", display: "flex", alignItems: "center", gap: 14 }}>
                  <div style={{ width: 46, height: 46, borderRadius: "50%", background: avatarBg(emp), display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, fontWeight: 800, color: "#fff", flexShrink: 0 }}>{emp.avatar}</div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 700, fontSize: 15, color: "#f1f5f9" }}>
                      {emp.name}{emp.isManager ? " 👑" : ""}{emp.lang === "es" ? " 🇲🇽" : ""}
                    </div>
                    <div style={{ fontSize: 12, color: "#64748b", marginTop: 2 }}>{emp.role} · {emp.workdays}</div>
                    <div style={{ display: "flex", gap: 6, marginTop: 8 }}>
                      <span style={{ fontSize: 10, background: "#0c2340", color: "#60a5fa", borderRadius: 4, padding: "2px 8px", fontWeight: 600 }}>
                        {getEmployeeDeliveries(emp.id).length} deliveries today
                      </span>
                      <span style={{ fontSize: 10, background: emp.lang === "es" ? "#052e16" : "#1e293b", color: emp.lang === "es" ? "#4ade80" : "#94a3b8", borderRadius: 4, padding: "2px 8px", fontWeight: 600 }}>
                        {emp.lang === "es" ? "ES" : "EN"}
                      </span>
                    </div>
                  </div>
                  {!emp.isManager && (
                    confirmDelete === emp.id ? (
                      <div style={{ display: "flex", flexDirection: "column", gap: 6, alignItems: "flex-end" }}>
                        <div style={{ fontSize: 11, color: "#f87171" }}>Remove {emp.name}?</div>
                        <div style={{ display: "flex", gap: 6 }}>
                          <button className="btn" onClick={() => removeEmployee(emp.id)}
                            style={{ background: "#dc2626", color: "#fff", padding: "5px 12px", fontSize: 11 }}>Yes</button>
                          <button className="btn" onClick={() => setConfirmDelete(null)}
                            style={{ background: "#1e2d3d", color: "#94a3b8", padding: "5px 12px", fontSize: 11 }}>Cancel</button>
                        </div>
                      </div>
                    ) : (
                      <button className="btn" onClick={() => setConfirmDelete(emp.id)}
                        style={{ background: "#1e2d3d", color: "#64748b", padding: "7px 12px", fontSize: 12, flexShrink: 0 }}>
                        ✕ Remove
                      </button>
                    )
                  )}
                  {emp.isManager && (
                    <span style={{ fontSize: 11, color: "#7c3aed", background: "#1e1038", borderRadius: 6, padding: "5px 10px", flexShrink: 0, fontWeight: 600 }}>Owner</span>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}
